    "G/18": {
        1: [
            {
                text: `building a house`,
                x: `14.04%`,
                y: `5.19%`,
                width: `61.89%`,
                height: `6.39%`,
            },
        ],
        3: [
            {
                text: `houses do not all look the same, but most home builders follow the same basic steps.`,
                x: `16.88%`,
                y: `75.28%`,
                width: `72.53%`,
                height: `14.35%`,
            },
        ],
        4: [
            {
                text: `First, the builders make a strong base for the house.`,
                x: `7.45%`,
                y: `70.46%`,
                width: `63.90%`,
                height: `8.98%`,
            },
            {
                text: `the base is called the foundation.`,
                x: `7.45%`,
                y: `80.28%`,
                width: `52.72%`,
                height: `8.52%`,
            },
        ],
        5: [
            {
                text: `Next, the builders add the floors, walls, and roof.`,
                x: `16.60%`,
                y: `80.19%`,
                width: `62.95%`,
                height: `9.17%`,
            },
        ],
        6: [
            {
                text: `Then, the builders cover the roof and outside walls to keep the rain out.`,
                x: `7.88%`,
                y: `60.56%`,
                width: `73.21%`,
                height: `13.80%`,
            },
            {
                text: `they leave the inside walls open so things can go inside them.`,
                x: `7.59%`,
                y: `75.37%`,
                width: `69.77%`,
                height: `13.61%`,
            },
        ],
        7: [
            {
                text: `Next, the builders put in the windows and doors.`,
                x: `16.60%`,
                y: `80.09%`,
                width: `57.80%`,
                height: `8.89%`,
            },
        ],
        8: [
            {
                text: `Then, the builders put wires and pipes inside the walls.`,
                x: `7.45%`,
                y: `80.28%`,
                width: `66.76%`,
                height: `9.17%`,
            },
        ],
        9: [
            {
                text: `Next, the builders fill the empty spaces inside the walls and under the roof.`,
                x: `16.45%`,
                y: `60.46%`,
                width: `61.37%`,
                height: `13.80%`,
            },
            {
                text: `this helps keep the house warm in winter and cool in summer.`,
                x: `16.88%`,
                y: `75.37%`,
                width: `61.52%`,
                height: `13.89%`,
            },
        ],
        10: [
            {
                text: `Then, the builders close up the walls and ceilings.`,
                x: `7.59%`,
                y: `65.56%`,
                width: `60.17%`,
                height: `9.26%`,
            },
            {
                text: `now the floors can be covered and the walls can be painted.`,
                x: `7.31%`,
                y: `75.37%`,
                width: `56.02%`,
                height: `13.98%`,
            },
        ],
        11: [
            {
                text: `Next, the builders put in all the lights and light switches.`,
                x: `16.45%`,
                y: `80.00%`,
                width: `74.11%`,
                height: `9.44%`,
            },
        ],
        12: [
            {
                text: `Finally, the builders put in the kitchen and the bathrooms.`,
                x: `8.17%`,
                y: `70.37%`,
                width: `69.77%`,
                height: `9.26%`,
            },
            {
                text: `Now, the house is ready to become someone's home!`,
                x: `7.59%`,
                y: `80.37%`,
                width: `64.47%`,
                height: `8.89%`,
            },
        ],
    },
