    "G/25": {
        1: [
            {
                text: `going to the dentist`,
                x: `6.88%`,
                y: `4.44%`,
                width: `75.21%`,
                height: `7.31%`,
            },
        ],
        3: [
            {
                text: `going to the dentist`,
                x: `20.06%`,
                y: `4.54%`,
                width: `67.34%`,
                height: `18.89%`,
            },
        ],
        5: [
            {
                text: `I'm going to the dentist. I'm a little scared.`,
                x: `16.33%`,
                y: `79.72%`,
                width: `58.02%`,
                height: `9.17%`,
            },
        ],
        6: [
            {
                text: `a friendly woman named jamie asks me to wait.`,
                x: `6.29%`,
                y: `70.09%`,
                width: `64.52%`,
                height: `9.26%`,
            },
            {
                text: `she says i can read, play with toys, or watch a movie.`,
                x: `7.58%`,
                y: `79.91%`,
                width: `68.81%`,
                height: `9.26%`,
            },
        ],
        7: [
            {
                text: `after a few minutes, dana calls my name.`,
                x: `16.19%`,
                y: `75.00%`,
                width: `52.87%`,
                height: `9.44%`,
            },
            {
                text: `dana is the dentist's helper.`,
                x: `17.34%`,
                y: `84.81%`,
                width: `67.34%`,
                height: `4.81%`,
            },
        ],
        8: [
            {
                text: `dana shows me around the office.`,
                x: `8.30%`,
                y: `70.19%`,
                width: `58.08%`,
                height: `8.80%`,
            },
            {
                text: `she teaches me how to clean my teeth at home.`,
                x: `8.01%`,
                y: `79.63%`,
                width: `71.67%`,
                height: `9.17%`,
            },
        ],
        9: [
            {
                text: `dana says she will make my teeth super clean.`,
                x: `17.05%`,
                y: `60.28%`,
                width: `60.89%`,
                height: `9.72%`,
            },
            {
                text: `she shows me the tools she will use.`,
                x: `17.34%`,
                y: `70.19%`,
                width: `56.59%`,
                height: `8.98%`,
            },
            {
                text: `some of the tools look scary, but the cleaning doesn't hurt.`,
                x: `16.76%`,
                y: `79.81%`,
                width: `71.78%`,
                height: `9.63%`,
            },
        ],
        10: [
            {
                text: `Next, dana takes special pictures of my teeth.`,
                x: `7.73%`,
                y: `79.63%`,
                width: `62.37%`,
                height: `10.37%`,
            },
        ],
        11: [
            {
                text: `the dentist comes to check my teeth.`,
                x: `16.91%`,
                y: `70.19%`,
                width: `65.62%`,
                height: `9.44%`,
            },
            {
                text: `she looks at the pictures of my teeth.`,
                x: `16.91%`,
                y: `80.00%`,
                width: `60.17%`,
                height: `9.72%`,
            },
        ],
        12: [
            {
                text: `the dentist says i need a filling.`,
                x: `7.87%`,
                y: `70.37%`,
                width: `55.94%`,
                height: `9.26%`,
            },
            {
                text: `i will have to come back another day.`,
                x: `8.30%`,
                y: `80.09%`,
                width: `59.94%`,
                height: `9.72%`,
            },
        ],
        13: [
            {
                text: `i ask if getting the filling will hurt.`,
                x: `16.91%`,
                y: `70.19%`,
                width: `58.60%`,
                height: `8.70%`,
            },
            {
                text: `the dentist says it won't hurt much because it will be small.`,
                x: `16.91%`,
                y: `80.00%`,
                width: `72.92%`,
                height: `8.98%`,
            },
        ],
        14: [
            {
                text: `the dentist says it's good we found the problem early.`,
                x: `7.87%`,
                y: `65.28%`,
                width: `69.96%`,
                height: `9.44%`,
            },
            {
                text: `I'm not happy i need a filling, but I'm glad i went to the dentist!`,
                x: `8.30%`,
                y: `75.19%`,
                width: `68.24%`,
                height: `13.61%`,
            },
        ],
    },
