    "G/29": {
        1: [
            {
                text: `groundhog goes outside`,
                x: `16.76%`,
                y: `4.72%`,
                width: `54.15%`,
                height: `11.76%`,
            },
        ],
        5: [
            {
                text: `it was the deep of winter.`,
                x: `17.48%`,
                y: `70.28%`,
                width: `64.90%`,
                height: `4.35%`,
            },
            {
                text: `gus was worried.`,
                x: `15.90%`,
                y: `75.19%`,
                width: `45.56%`,
                height: `4.17%`,
            },
            {
                text: `he couldn't find his shadow anywhere.`,
                x: `16.19%`,
                y: `80.19%`,
                width: `69.20%`,
                height: `9.35%`,
            },
        ],
        6: [
            {
                text: `'Have you seen my shadow? gus asked Dad.`,
                x: `6.15%`,
                y: `70.28%`,
                width: `73.82%`,
                height: `8.89%`,
            },
            {
                text: `'When did you see it last? dad asked.`,
                x: `6.01%`,
                y: `80.19%`,
                width: `67.10%`,
                height: `8.80%`,
            },
        ],
        7: [
            {
                text: `'Have you seen my shadow? gus asked Mom.`,
                x: `15.19%`,
                y: `70.00%`,
                width: `73.93%`,
                height: `9.81%`,
            },
            {
                text: `'Go back, step by step, until you find it, mom said.`,
                x: `14.61%`,
                y: `80.19%`,
                width: `69.63%`,
                height: `9.44%`,
            },
        ],
        8: [
            {
                text: `'Have you seen my shadow? gus asked Grace.`,
                x: `6.15%`,
                y: `69.91%`,
                width: `73.25%`,
                height: `9.35%`,
            },
            {
                text: `'Try looking where you left it, grace said.`,
                x: `5.72%`,
                y: `80.09%`,
                width: `58.66%`,
                height: `9.26%`,
            },
        ],
        9: [
            {
                text: `gus stopped looking.`,
                x: `15.04%`,
                y: `69.91%`,
                width: `55.73%`,
                height: `5.00%`,
            },
            {
                text: `he began to shout: 'HAS anybody seen my SHADOW?`,
                x: `15.90%`,
                y: `75.28%`,
                width: `52.87%`,
                height: `13.80%`,
            },
        ],
        10: [
            {
                text: `'Have you tried looking outside? asked Dad.`,
                x: `6.29%`,
                y: `55.65%`,
                width: `80.83%`,
                height: `8.98%`,
            },
            {
                text: `gus hadn't been outside in months.`,
                x: `7.30%`,
                y: `65.37%`,
                width: `62.23%`,
                height: `9.07%`,
            },
            {
                text: `he hadn't seen his shadow in months.`,
                x: `8.01%`,
                y: `75.19%`,
                width: `66.24%`,
                height: `8.89%`,
            },
            {
                text: `maybe his shadow was outside!`,
                x: `7.30%`,
                y: `85.00%`,
                width: `77.54%`,
                height: `4.35%`,
            },
        ],
        11: [
            {
                text: `gus left the burrow and went outside.`,
                x: `16.76%`,
                y: `50.56%`,
                width: `74.64%`,
                height: `9.26%`,
            },
            {
                text: `as soon as he did, someone began to cheer.`,
                x: `16.48%`,
                y: `60.56%`,
                width: `70.92%`,
                height: `8.98%`,
            },
            {
                text: `children waved and jumped up and down.`,
                x: `16.33%`,
                y: `70.46%`,
                width: `72.49%`,
                height: `8.61%`,
            },
            {
                text: `people shot photos of him. they all looked really happy.`,
                x: `17.34%`,
                y: `80.09%`,
                width: `71.20%`,
                height: `9.91%`,
            },
        ],
        12: [
            {
                text: `gus forgot about his shadow. gus was a star!`,
                x: `8.01%`,
                y: `79.81%`,
                width: `72.96%`,
                height: `8.89%`,
            },
        ],
        13: [
            {
                text: `back in the burrow, his family gathered around him.`,
                x: `17.34%`,
                y: `70.28%`,
                width: `72.49%`,
                height: `9.44%`,
            },
            {
                text: `gus grinned from ear to ear. 'Did you find it? asked Mom.`,
                x: `14.47%`,
                y: `80.19%`,
                width: `77.08%`,
                height: `9.44%`,
            },
        ],
        14: [
            {
                text: `'Find what? asked Gus.`,
                x: `6.44%`,
                y: `85.09%`,
                width: `59.94%`,
                height: `4.35%`,
            },
        ],
    },
