    "G/58": {
        2: [
            { text: `rude robot`, x: `14.43%`, y: `8.00%`, width: `68.81%`, height: `10.83%` },
        ],
        3: [
            { text: `rob opened his huge birthday present.`, x: `11.08%`, y: `70.25%`, width: `54.64%`, height: `9.42%` },
            { text: `'A talking robot! said Rob. 'Tl name you Bott!`, x: `9.02%`, y: `80.00%`, width: `68.30%`, height: `9.83%` },
        ],
        4: [
            { text: `rob took bott to meet alll of his friends.`, x: `11.98%`, y: `70.00%`, width: `63.79%`, height: `9.33%` },
            { text: `but one by one, his friends stopped playing with Bott.`, x: `12.76%`, y: `80.00%`, width: `67.91%`, height: `10.08%` },
        ],
        5: [
            { text: `rob soon found out why.`, x: `11.08%`, y: `70.00%`, width: `63.66%`, height: `4.92%` },
            { text: `bott was rude to people.`, x: `10.82%`, y: `75.25%`, width: `63.27%`, height: `4.67%` },
            { text: `he never said hello or please or thank you.`, x: `11.47%`, y: `80.42%`, width: `74.48%`, height: `9.17%` },
        ],
        6: [
            { text: `bott sat like a big tin can when grandma came to visit.`, x: `11.98%`, y: `70.25%`, width: `75.52%`, height: `9.08%` },
            { text: `'You should say nice to meet you, rob said.`, x: `10.82%`, y: `80.17%`, width: `60.18%`, height: `9.08%` },
        ],
        7: [
            { text: `'Being rude isn't cool, rob said.`, x: `9.41%`, y: `65.33%`, width: `59.02%`, height: `8.92%` },
            { text: `'A robot can learn anything. so you can learn good manners, he said.`, x: `9.79%`, y: `75.42%`, width: `72.29%`, height: `13.83%` },
        ],
        8: [
            { text: `bott nodded, and burped.`, x: `11.34%`, y: `65.25%`, width: `67.14%`, height: `4.58%` },
            { text: `'Say excuse me when you burp, said Rob.`, x: `10.18%`, y: `70.33%`, width: `67.78%`, height: `8.67%` },
            { text: `'Excuse me, said the robot. 'Good job! said Rob.`, x: `10.70%`, y: `80.33%`, width: `69.97%`, height: `9.67%` },
        ],
        9: [
            { text: `rob gave bott a new battery. 'Do i say excuse me?`, x: `10.95%`, y: `65.33%`, width: `75.00%`, height: `9.33%` },
            { text: `bott asked.`, x: `9.66%`, y: `75.58%`, width: `31.70%`, height: `3.75%` },
            { text: `'No, you say thank you when a person helps you.`, x: `9.15%`, y: `80.17%`, width: `76.80%`, height: `10.08%` },
        ],
        10: [
            { text: `bott burped again and nodded.`, x: `11.21%`, y: `65.17%`, width: `60.31%`, height: `9.25%` },
            { text: `he learned when to say hello and please and thank you.`, x: `11.98%`, y: `75.33%`, width: `75.13%`, height: `9.08%` },
            { text: `'This is easy! bott said.`, x: `10.70%`, y: `85.08%`, width: `57.99%`, height: `4.75%` },
        ],
        11: [
            { text: `Soon, bott opened doors for people.`, x: `10.31%`, y: `60.58%`, width: `64.82%`, height: `9.33%` },
            { text: `he used his napkin.`, x: `10.57%`, y: `70.67%`, width: `49.23%`, height: `4.17%` },
            { text: `he waited for his turn to talk.`, x: `10.57%`, y: `75.50%`, width: `73.84%`, height: `4.00%` },
            { text: `'Bott is so cooll said Rob's friends.`, x: `9.66%`, y: `80.17%`, width: `53.48%`, height: `9.42%` },
        ],
        12: [
            { text: `'You're the best robot in the world, said Grandma.`, x: `10.95%`, y: `65.17%`, width: `71.52%`, height: `9.17%` },
            { text: `'Thank you, said Bott, as he burped.`, x: `10.57%`, y: `75.08%`, width: `57.35%`, height: `9.42%` },
            { text: `'And excuse me, he said.`, x: `10.31%`, y: `85.17%`, width: `66.11%`, height: `4.33%` },
        ],
    },
